","body {
 margin: 0;
 padding: 0;
 font-family: var(--now-font-family, sans-serif);
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
 -webkit-font-smoothing: antialiased;
}

.fc-shell { min-height: 100vh; }

.fc-header {
 padding: 1.25rem 1.5rem;
 background: rgb(var(--now-color_background--secondary, 245, 246, 247));
 border-bottom: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
}
.fc-header-title { font-size: 1.25rem; font-weight: 700; }
.fc-header-sub { font-size: 0.8125rem; color: rgb(var(--now-color_text--secondary, 75, 85, 89)); margin-top: 2px; }

.fc-content { padding: 1rem 1.5rem; max-width: 1200px; }

/* Notice banner */
.fc-notice {
 padding: 0.75rem 1rem;
 background: #fff8e1;
 border: 1px solid #ffe082;
 border-radius: 6px;
 margin-bottom: 1rem;
}
.fc-notice-title { font-size: 0.8125rem; font-weight: 600; color: #e65100; margin-bottom: 4px; }
.fc-notice-text { font-size: 0.8125rem; color: #424242; line-height: 1.5; }

/* Summary cards */
.fc-cards {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
 gap: 0.75rem;
 margin-bottom: 1.25rem;
}
.fc-card {
 padding: 0.75rem;
 border: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
 border-radius: 6px;
 text-align: center;
}
.fc-card-value { font-size: 1.5rem; font-weight: 700; }
.fc-card-label { font-size: 0.75rem; color: rgb(var(--now-color_text--secondary, 75, 85, 89)); margin-top: 2px; }
.fc-card--critical { border-left: 3px solid #b71c1c; }
.fc-card--critical .fc-card-value { color: #b71c1c; }
.fc-card--low { border-left: 3px solid #f57f17; }
.fc-card--low .fc-card-value { color: #f57f17; }
.fc-card--adequate { border-left: 3px solid #2e7d32; }
.fc-card--adequate .fc-card-value { color: #2e7d32; }

/* Toolbar */
.fc-toolbar {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 0.75rem;
}
.fc-toolbar-title { font-size: 0.875rem; font-weight: 600; }

/* States */
.fc-error {
 padding: 0.5rem 0.75rem;
 background: #fde2e6;
 color: #b30317;
 border-radius: 4px;
 font-size: 0.8125rem;
 font-weight: 600;
 margin-bottom: 0.75rem;
}
.fc-loading, .fc-empty {
 padding: 2rem;
 text-align: center;
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
 font-size: 0.875rem;
}

/* Table */
.fc-table-wrap { overflow-x: auto; margin-bottom: 1.5rem; }
.fc-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 0.8125rem;
}
.fc-table th {
 text-align: left;
 padding: 0.5rem 0.75rem;
 font-weight: 600;
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
 border-bottom: 2px solid rgb(var(--now-container--border-color, 207, 213, 215));
 white-space: nowrap;
}
.fc-table td {
 padding: 0.5rem 0.75rem;
 border-bottom: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
 vertical-align: top;
}
.fc-mat-name { font-weight: 600; }
.fc-mat-cat { font-size: 0.75rem; color: rgb(var(--now-color_text--secondary, 75, 85, 89)); }
.fc-badge {
 display: inline-block;
 padding: 2px 8px;
 border-radius: 10px;
 font-size: 0.75rem;
 font-weight: 600;
 white-space: nowrap;
}

/* Section title */
.fc-section-title {
 font-size: 0.875rem;
 font-weight: 600;
 margin-bottom: 0.75rem;
 padding-top: 0.5rem;
}

/* Forecast placeholder */
.fc-placeholder {
 padding: 2rem;
 text-align: center;
 border: 2px dashed rgb(var(--now-container--border-color, 207, 213, 215));
 border-radius: 8px;
 background: rgb(var(--now-color_background--secondary, 245, 246, 247));
}
.fc-placeholder-icon { font-size: 2rem; margin-bottom: 0.5rem; }
.fc-placeholder-title { font-size: 1rem; font-weight: 600; margin-bottom: 0.5rem; }
.fc-placeholder-text { font-size: 0.8125rem; color: rgb(var(--now-color_text--secondary, 75, 85, 89)); line-height: 1.5; max-width: 500px; margin: 0 auto 0.75rem; }
.fc-placeholder-sub { font-size: 0.75rem; color: #999; font-style: italic; }
