 // Fetch materials
 const matRes = await fetch(
 `/api/now/table/${MAT_TABLE}?sysparm_fields=sys_id,material_name,category,unit_of_measure,safety_stock_level,reorder_level&sysparm_display_value=all&sysparm_limit=50&sysparm_query=active=true`,
 { headers: hdrs }
 );
 const matData = await matRes.json();
 const mats = matData.result || [];

 // Fetch stock aggregated by material
 const stockRes = await fetch(
 `/api/now/table/${STOCK_TABLE}?sysparm_fields=material_product,total_quantity,available_quantity,reserved_quantity&sysparm_display_value=all&sysparm_limit=200&sysparm_query=active=true`,
 { headers: hdrs }
 );
 const stockData = await stockRes.json();
 const stocks = stockData.result || [];

 // Group stock by material product sys_id
 const stockMap: Record<string, { total: number; available: number; reserved: number }> = {};
 for (const s of stocks) {
 const matId = s.material_product?.value || "";
 if (!matId) continue;
 if (!stockMap[matId]) stockMap[matId] = { total: 0, available: 0, reserved: 0 };
 stockMap[matId].total += parseFloat(s.total_quantity?.value || "0");
 stockMap[matId].available += parseFloat(s.available_quantity?.value || "0");
 stockMap[matId].reserved += parseFloat(s.reserved_quantity?.value || "0");
 }

 const rows: MaterialRow[] = mats.map((m: any) => {
 const sid = m.sys_id?.value || m.sys_id || "";
 const stk = stockMap[sid] || { total: 0, available: 0, reserved: 0 };
 const safety = parseFloat(m.safety_stock_level?.value || "0");
 const reorder = parseFloat(m.reorder_level?.value || "0");

 let coverageStatus: MaterialRow["coverageStatus"] = "none";
 if (stk.total > 0) {
 if (stk.available <= 0) coverageStatus = "critical";
 else if (safety > 0 && stk.available <= safety) coverageStatus = "critical";
 else if (reorder > 0 && stk.available <= reorder) coverageStatus = "low";
 else coverageStatus = "adequate";
 }

 return {
 sys_id: sid,
 name: m.material_name?.display_value || "",
 category: m.category?.display_value || "",
 unit: m.unit_of_measure?.display_value || "",
 safetyStock: safety > 0 ? safety.toString() : "—",
 reorderLevel: reorder > 0 ? reorder.toString() : "—",
 totalStock: stk.total.toString(),
 availableStock: stk.available.toString(),
 reservedStock: stk.reserved.toString(),
 coverageStatus,
 };
 });

 setMaterials(rows);
 } catch (e) {
 setError("Failed to load data. Please try again.");
 }
 setLoading(false);
 }

 const coverageLabel: Record<string, { label: string; bg: string; color: string }> = {
 adequate: { label: "Adequate", bg: "#c8e6c9", color: "#2e7d32" },
 low: { label: "Low", bg: "#fff9c4", color: "#f57f17" },
 critical: { label: "Critical", bg: "#ffcdd2", color: "#b71c1c" },
 none: { label: "No Stock", bg: "#f5f5f5", color: "#9e9e9e" },
 };

 return (
 <div className="fc-shell">
 <div className="fc-header">
 <div className="fc-header-title">Demand Forecasting</div>
 <div className="fc-header-sub">Inventory Coverage &amp; Demand Analysis</div>
 </div>

 <div className="fc-content">
 {/* Forecast Source Banner */}
 <div className="fc-notice">
 <div className="fc-notice-title">External Forecast Source</div>
 <div className="fc-notice-text">
 No external forecasting service is currently connected. The data below shows current
 inventory levels and coverage indicators based on safety stock and reorder thresholds.
 Predictive demand forecasting will be available when an external forecasting API is
 integrated.
 </div>
 </div>

 {/* Summary Cards */}
 <div className="fc-cards">
 <div className="fc-card">
 <div className="fc-card-value">{materials.length}</div>
 <div className="fc-card-label">Materials Tracked</div>
 </div>
 <div className="fc-card fc-card--critical">
 <div className="fc-card-value">{materials.filter((m) => m.coverageStatus === "critical").length}</div>
 <div className="fc-card-label">Critical Coverage</div>
 </div>
 <div className="fc-card fc-card--low">
 <div className="fc-card-value">{materials.filter((m) => m.coverageStatus === "low").length}</div>
 <div className="fc-card-label">Low Coverage</div>
 </div>
 <div className="fc-card fc-card--adequate">
 <div className="fc-card-value">{materials.filter((m) => m.coverageStatus === "adequate").length}</div>
 <div className="fc-card-label">Adequate Coverage</div>
 </div>
 </div>

 {/* Toolbar */}
 <div className="fc-toolbar">
 <div className="fc-toolbar-title">Material Inventory Coverage</div>
 <Button label={loading ? "Loading…" : "Refresh"} variant="secondary" size="sm" disabled={loading} onClick={loadData} />
 </div>

 {/* Error */}
 {error && <div className="fc-error">{error}</div>}

 {/* Loading */}
 {loading && materials.length === 0 && (
 <div className="fc-loading">Loading materials…</div>
 )}

 {/* Table */}
 {!loading && materials.length === 0 && !error && (
 <div className="fc-empty">No materials found. Materials will appear here when material master records are created.</div>
 )}

 {materials.length > 0 && (
 <div className="fc-table-wrap">
 <table className="fc-table">
 <thead>
 <tr>
 <th>Material</th>
 <th>Available</th>
 <th>Reserved</th>
 <th>Safety</th>
 <th>Coverage</th>
 </tr>
 </thead>
 <tbody>
 {materials.map((m) => {
 const cv = coverageLabel[m.coverageStatus];
 return (
 <tr key={m.sys_id}>
 <td>
 <div className="fc-mat-name">{m.name}</div>
 {m.category && <div className="fc-mat-cat">{m.category}</div>}
 </td>
 <td>{m.availableStock} {m.unit}</td>
 <td>{m.reservedStock}</td>
 <td>{m.safetyStock}</td>
 <td>
 <span className="fc-badge" style={{ backgroundColor: cv.bg, color: cv.color }}>{cv.label}</span>
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 )}

 {/* Forecast Placeholder */}
 <div className="fc-section-title">Demand Forecast</div>
 <div className="fc-placeholder">
 <div className="fc-placeholder-icon">📊</div>
 <div className="fc-placeholder-title">Forecast Data Unavailable</div>
 <div className="fc-placeholder-text">
 Demand forecasting requires an external forecasting service or historical demand model.
 When connected, this section will show predicted demand by product, forecast quantities,
 forecast periods, and demand coverage analysis against current inventory.
 </div>
 <div className="fc-placeholder-sub">
 The SourcingEngine includes a basic 90-day rolling average that can be used as a
 starting point. Connect an external forecasting API for production-grade predictions.
 </div>
 </div>
 </div>
 </div>
 );
}
